#!/usr/bin/env python3
"""Generate the independent high-precision references embedded in
tests/student_t_x87_guard_contract.cpp (issue #18).

mpmath, 60 significant digits: two-sided P(|T| > t) = I_{df/(df+t^2)}(df/2, 1/2)
(regularized incomplete beta) and its inverse by bisection to 1e-45 relative,
each rounded once to the nearest binary64.  No xhdfe code is used.
Usage: python3 make_student_t_x87_reference.py > table.inc
"""
import mpmath as mp

mp.mp.dps = 60
WINDOWS_REFUSED_N = (138704, 138705, 138708, 138713, 138715, 138725, 138727, 138729, 138730, 138734,
                     138742, 138746, 138752, 138754, 138757, 138759, 138765, 138768, 138769, 138771,
                     138776, 138785, 138786, 138787, 138789, 138790, 138791, 138795)
DFS = ([n - 2 for n in WINDOWS_REFUSED_N] + [138700, 138799, 500000, 1500000, 5000000, 20000000,
       100000000, 1000000000000, 1, 2, 10, 30, 1000, 99999, 100000, 1000000])
TAILS = (0.025, 0.005, 0.05)
TS = (1.96, 3.5, 9.338)


def two_sided(t, df):
    t, df = mp.mpf(t), mp.mpf(df)
    return mp.betainc(df / 2, mp.mpf(1) / 2, 0, df / (df + t * t), regularized=True)


def quantile(tail, df):
    target = 2 * mp.mpf(tail)
    lo, hi = mp.mpf(0), mp.mpf(2)
    while two_sided(hi, df) > target:
        lo, hi = hi, hi * 2
    while hi - lo > mp.mpf(10) ** -45 * hi:
        mid = (lo + hi) / 2
        lo, hi = (mid, hi) if two_sided(mid, df) > target else (lo, mid)
    return (lo + hi) / 2


print(f"// generated by tests/fixtures/make_student_t_x87_reference.py, mpmath {mp.__version__}, dps {mp.mp.dps}")
for df in DFS:
    for tail in TAILS:
        print(f"    {{'Q', {float(df).hex()}, {float(tail).hex()}, {float(quantile(tail, df)).hex()}}},")
    for t in TS:
        print(f"    {{'P', {float(df).hex()}, {float(t).hex()}, {float(two_sided(t, df)).hex()}}},")
